// Backstop: read last poll state, emit fetch params
const sd = $getWorkflowStaticData('global');
const lastSha = sd.lastCommitSha || '';
const lastPoll = sd.lastPollTime || '';
// MVP: single repo config — user replaces project ID
const projectId = 'REPLACE_GITLAB_PROJECT_ID';
return [{
  json: {
    projectId: projectId,
    since: lastPoll, // ISO timestamp of last poll
    lastSha: lastSha,
  },
}];

// Update dedup pointer to latest commit, pass through commits
const sd = $getWorkflowStaticData('global');
const commits = $json; // HTTP response is array of commits
if (commits && commits.length > 0) {
  const latest = commits[0]; // GitLab returns newest first
  sd.lastCommitSha = latest.id;
  sd.lastPollTime = latest.committed_date || new Date().toISOString();
}
// Pass through each commit as an item
const items = [];
for (const c of (commits || [])) {
  items.push({json: c});
}
return items;

const PROJECTS = {
  DEV: {
    uuid: 'b5842796-7af7-474c-bf17-012977399c16',
    states: {
      backlog: 'e3bde020-6ce7-4b87-b994-2ebb28c14d84',
      todo: '6af7ed32-6610-44e3-be3f-f405b16d2d35',
      inProgress: '16099284-4b49-4ed3-af2a-d99e21d0e154',
      inReview: 'a24250ec-212a-49ee-ad59-6d31e8b181ae',
      done: '56c26d40-418d-4d71-8f49-ecf0ba0837ad',
      cancelled: 'c69e0a4f-6fa8-4aa6-85c8-26a8162db905',
    },
  },
};
const WORKSPACE_SLUG = 'REPLACE_WORKSPACE_SLUG';
const ISSUE_RE = /(?<![A-Z0-9])([A-Z][A-Z0-9]+-\d+)(?![A-Z0-9-])/g;
const CLOSE_RE = /\b(closes|fixes|resolves)\s+([A-Z][A-Z0-9]+-\d+)\b/g;
const REOPEN_RE = /\b(reopens)\s+([A-Z][A-Z0-9]+-\d+)\b/g;

function classifyMessage(message) {
  // Returns array of {issueKey, action} where action in: close, reopen, mention
  const results = [];
  const seen = new Set();
  let m;
  CLOSE_RE.lastIndex = 0;
  while ((m = CLOSE_RE.exec(message)) !== null) {
    const key = m[2];
    if (!seen.has(key + ':close')) { results.push({issueKey: key, action: 'close'}); seen.add(key + ':close'); }
  }
  REOPEN_RE.lastIndex = 0;
  while ((m = REOPEN_RE.exec(message)) !== null) {
    const key = m[2];
    if (!seen.has(key + ':reopen')) { results.push({issueKey: key, action: 'reopen'}); seen.add(key + ':reopen'); }
  }
  ISSUE_RE.lastIndex = 0;
  while ((m = ISSUE_RE.exec(message)) !== null) {
    const key = m[1];
    if (!seen.has(key + ':close') && !seen.has(key + ':reopen') && !seen.has(key + ':mention')) {
      results.push({issueKey: key, action: 'mention'}); seen.add(key + ':mention');
    }
  }
  return results;
}

function htmlEscape(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// Backstop normalize commits (same as Normalize Push but single commit per item)
const commit = $json;
const msg = commit.message || '';
const refs = classifyMessage(msg);
const items = [];
for (const r of refs) {
  items.push({
    json: {
      issueKey: r.issueKey,
      action: r.action === 'close' ? 'mention' : r.action, // closes without MR context = mention in backstop
      commitSha: commit.id,
      commitUrl: commit.web_url || '',
      commitMessage: msg,
      commitTitle: commit.title || msg.split('\n')[0],
      author: commit.author_name || '',
      branch: '',
      isDefaultBranch: false, // backstop can't easily tell; reducer treats as feature branch
      source: 'push',
      isBackstop: true,
    },
  });
}
return items;

const PROJECTS = {
  DEV: {
    uuid: 'b5842796-7af7-474c-bf17-012977399c16',
    states: {
      backlog: 'e3bde020-6ce7-4b87-b994-2ebb28c14d84',
      todo: '6af7ed32-6610-44e3-be3f-f405b16d2d35',
      inProgress: '16099284-4b49-4ed3-af2a-d99e21d0e154',
      inReview: 'a24250ec-212a-49ee-ad59-6d31e8b181ae',
      done: '56c26d40-418d-4d71-8f49-ecf0ba0837ad',
      cancelled: 'c69e0a4f-6fa8-4aa6-85c8-26a8162db905',
    },
  },
};
const WORKSPACE_SLUG = 'REPLACE_WORKSPACE_SLUG';
const ISSUE_RE = /(?<![A-Z0-9])([A-Z][A-Z0-9]+-\d+)(?![A-Z0-9-])/g;
const CLOSE_RE = /\b(closes|fixes|resolves)\s+([A-Z][A-Z0-9]+-\d+)\b/g;
const REOPEN_RE = /\b(reopens)\s+([A-Z][A-Z0-9]+-\d+)\b/g;

function classifyMessage(message) {
  // Returns array of {issueKey, action} where action in: close, reopen, mention
  const results = [];
  const seen = new Set();
  let m;
  CLOSE_RE.lastIndex = 0;
  while ((m = CLOSE_RE.exec(message)) !== null) {
    const key = m[2];
    if (!seen.has(key + ':close')) { results.push({issueKey: key, action: 'close'}); seen.add(key + ':close'); }
  }
  REOPEN_RE.lastIndex = 0;
  while ((m = REOPEN_RE.exec(message)) !== null) {
    const key = m[2];
    if (!seen.has(key + ':reopen')) { results.push({issueKey: key, action: 'reopen'}); seen.add(key + ':reopen'); }
  }
  ISSUE_RE.lastIndex = 0;
  while ((m = ISSUE_RE.exec(message)) !== null) {
    const key = m[1];
    if (!seen.has(key + ':close') && !seen.has(key + ':reopen') && !seen.has(key + ':mention')) {
      results.push({issueKey: key, action: 'mention'}); seen.add(key + ':mention');
    }
  }
  return results;
}

function htmlEscape(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// REDUCER: group raw actions by issue, apply precedence + guards, emit final decision
// Reads items from input. isBackstop flag restricts downgrades.
const isBackstop = true;

// Collect all input items (n8n passes them in $items or via $input.all())
const allItems = $input.all ? $input.all().map(i => i.json) : items.map(i => i.json);
if (!allItems.length) return [];

// Group by issueKey
const groups = {};
for (const item of allItems) {
  const key = item.issueKey;
  if (!groups[key]) groups[key] = [];
  groups[key].push(item);
}

const results = [];
for (const issueKey of Object.keys(groups)) {
  const actions = groups[issueKey];
  const prefix = issueKey.split('-')[0];
  const proj = PROJECTS[prefix];
  if (!proj) continue; // unknown project prefix, skip

  // Determine the strongest action via precedence ladder
  // Precedence (highest): reopen > merged > close-in-mr > mr-open > mention > mr-closed
  const hasReopen = actions.some(a => a.action === 'reopen');
  const hasMerged = actions.some(a => a.action === 'merged');
  const hasCloseInMr = actions.some(a => a.action === 'close-in-mr');
  const hasMrOpen = actions.some(a => a.action === 'mr-open');
  const hasMention = actions.some(a => a.action === 'mention' || a.action === 'close');
  const hasMrClosed = actions.some(a => a.action === 'mr-closed');

  let desiredState = null;
  let actionLabel = '';
  let commentParts = [];

  if (hasReopen) {
    desiredState = proj.states.inProgress; actionLabel = 'reopen';
  } else if (hasMerged) {
    desiredState = proj.states.done; actionLabel = 'merged';
  } else if (hasCloseInMr) {
    desiredState = proj.states.inReview; actionLabel = 'close-in-mr';
  } else if (hasMrOpen) {
    desiredState = proj.states.inProgress; actionLabel = 'mr-open';
  } else if (hasMention) {
    desiredState = proj.states.inProgress; actionLabel = 'mention';
  } else if (hasMrClosed) {
    desiredState = proj.states.todo; actionLabel = 'mr-closed';
  }

  if (!desiredState) continue;

  // Build comment parts from actions
  for (const a of actions) {
    if (a.source === 'push' && a.commitUrl) {
      const shaShort = (a.commitSha || '').substring(0, 7);
      commentParts.push(`mentioned in commit <a href="${a.commitUrl}"><code>${shaShort}</code></a> by ${a.author || 'unknown'}: <i>${a.commitTitle || ''}</i>`);
    } else if (a.source === 'mr' && a.mrUrl) {
      commentParts.push(`MR <a href="${a.mrUrl}">!${a.mrIid || ''}: ${a.mrTitle || ''}</a>`);
    }
  }

  // External ID for comment dedup (Plane returns 409 on duplicate external_id)
  let externalId;
  if (actionLabel === 'merged' || actionLabel === 'close-in-mr' || actionLabel === 'mr-open' || actionLabel === 'mr-closed') {
    const a = actions.find(x => x.source === 'mr');
    externalId = `gitlab-mr-${a && a.mrIid}-${actionLabel}-${issueKey}`;
  } else {
    const a = actions.find(x => x.source === 'push' && x.commitSha);
    externalId = `gitlab-commit-${(a && a.commitSha) || 'unknown'}-${issueKey}`;
  }

  // GUARDS
  let shouldChangeState = true;
  let guardReason = '';

  // In backstop mode, restrict downgrades (Council direction #8)
  if (isBackstop && (actionLabel === 'mr-closed')) {
    shouldChangeState = false;
    guardReason = 'backstop: mr-closed downgrade not allowed in backstop mode';
  }

  // mr-closed -> Todo is a downgrade; only allowed in webhook mode
  // (handled above for backstop)

  // We cannot know the CURRENT state here (that comes after Get Work Item).
  // The guards that depend on current state (Done protection, Cancelled protection,
  // In Review protection) are applied in a LATER Code node after Get Work Item.
  // For now, emit the desired state + a flag; the post-fetch node re-evaluates.

  const sentinel = `<!-- n8n-bridge: src=${actions[0].source}, action=${actionLabel}, issue=${issueKey} -->`;

  results.push({
    json: {
      issueKey: issueKey,
      desiredStateName: actionLabel,
      targetStateUuid: desiredState,
      shouldChangeState: shouldChangeState,
      guardReason: guardReason,
      commentHtml: sentinel + '\n' + commentParts.join('<br>\n'),
      externalId: externalId,
      externalSource: 'gitlab',
      mrUrl: actions.find(x => x.mrUrl) ? actions.find(x => x.mrUrl).mrUrl : '',
      mrTitle: actions.find(x => x.mrTitle) ? actions.find(x => x.mrTitle).mrTitle : '',
      isBackstop: isBackstop,
      prefix: prefix,
    },
  });
}
return results;

// Post-fetch guard: re-evaluate shouldChangeState using current Plane state
const wi = $json; // work item from Get Work Item
const prevState = $json.state; // UUID of current state

// Pass-through fields from the previous node (stored in $items[0] before this node)
// n8n: we use $('Reducer').item or the incoming item. For simplicity the Get Work Item
// node passes through our reducer fields via expressions. Here we read them from $json
// which n8n merges. In practice the HTTP Request node replaces $json with the response,
// so we use the pairedItem mechanism. For MVP simplicity, we re-read from the previous
// code node output using $('Reducer').all()[index]. But n8n Code node gives us $input.

// We rely on the workflow wiring: Get Work Item passes through via "Include Original Items"
// is not available on HTTP Request by default. Instead we use expressions in the HTTP node
// response field. For MVP, this guard node reads from $input which contains the reducer
// output merged with the HTTP response via the workflow's item pairing.

// The simplest robust approach: this node receives the reducer output (with desiredStateUuid)
// AND the Get Work Item response (with id, project, state). We merge them.
// In n8n, when an HTTP Request follows a Code node, $json is the HTTP response.
// To access the reducer fields we use $('Reducer').all().

const reducerItems = $('Reducer').all();
const idx = $itemIndex || 0;
const r = reducerItems[idx] ? reducerItems[idx].json : {};

const projStates = {
  backlog: 'e3bde020-6ce7-4b87-b994-2ebb28c14d84',
  todo: '6af7ed32-6610-44e3-be3f-f405b16d2d35',
  inProgress: '16099284-4b49-4ed3-af2a-d99e21d0e154',
  inReview: 'a24250ec-212a-49ee-ad59-6d31e8b181ae',
  done: '56c26d40-418d-4d71-8f49-ecf0ba0837ad',
  cancelled: 'c69e0a4f-6fa8-4aa6-85c8-26a8162db905',
};
const stateNameByUuid = {};
for (const k of Object.keys(projStates)) stateNameByUuid[projStates[k]] = k;

const currentStateName = stateNameByUuid[wi.state] || 'unknown';
const targetStateName = stateNameByUuid[r.targetStateUuid] || 'unknown';
const actionLabel = r.desiredStateName || '';

let shouldChangeState = r.shouldChangeState;
let guardReason = r.guardReason || '';

// GUARD 1: Never touch Cancelled
if (currentStateName === 'cancelled') {
  shouldChangeState = false;
  guardReason = 'protected: Cancelled is human-owned';
}
// GUARD 2: Never downgrade Done except on explicit reopen
else if (currentStateName === 'done' && actionLabel !== 'reopen') {
  shouldChangeState = false;
  guardReason = 'protected: Done cannot be downgraded except by reopen';
}
// GUARD 3: Never downgrade In Review to In Progress from a bare mention
else if (currentStateName === 'inReview' && (actionLabel === 'mention' || actionLabel === 'mr-open')) {
  shouldChangeState = false;
  guardReason = 'protected: In Review not downgraded by bare mention';
}
// GUARD 4: Already in the target state -> no-op
else if (wi.state === r.targetStateUuid) {
  shouldChangeState = false;
  guardReason = 'already in target state';
}
// GUARD 5: mr-closed downgrade only from In Progress/In Review (not from Backlog/Todo/Done)
else if (actionLabel === 'mr-closed' && currentStateName !== 'inProgress' && currentStateName !== 'inReview') {
  shouldChangeState = false;
  guardReason = 'mr-closed: can only downgrade from In Progress/In Review';
}

return [{
  json: {
    issueKey: r.issueKey,
    workItemId: wi.id,
    project: wi.project,
    currentState: wi.state,
    currentStateName: currentStateName,
    targetStateUuid: r.targetStateUuid,
    targetStateName: targetStateName,
    shouldChangeState: shouldChangeState,
    guardReason: guardReason,
    commentHtml: r.commentHtml,
    externalId: r.externalId,
    externalSource: r.externalSource,
    mrUrl: r.mrUrl || '',
    mrTitle: r.mrTitle || '',
  },
}];
